import{_ as l,C as i,o,c as n,a0 as a,b as s,w as t,a as E,E as d,a1 as A}from"./chunks/framework.D-eu8Ik3.js";const B=JSON.parse('{"title":"01. ComfyUI 5大核心节点与底层数据流解析","description":"","frontmatter":{},"headers":[],"relativePath":"01-basics/01-core-nodes.md","filePath":"01-basics/01-core-nodes.md"}'),c={name:"01-basics/01-core-nodes.md"};function m(C,e,g,h,u,p){const r=i("Mermaid");return o(),n("div",null,[e[1]||(e[1]=a('<h1 id="_01-comfyui-5大核心节点与底层数据流解析" tabindex="-1">01. ComfyUI 5大核心节点与底层数据流解析 <a class="header-anchor" href="#_01-comfyui-5大核心节点与底层数据流解析" aria-label="Permalink to &quot;01. ComfyUI 5大核心节点与底层数据流解析&quot;">​</a></h1><blockquote><p><strong>学习目标</strong>：彻底摒弃黑盒思维，理解 ComfyUI 如何像搭积木一样，将文本转化为像素。跑通属于你的第一个“文生图”工作流。</p></blockquote><hr><h2 id="一、-为什么选择-comfyui-潜空间数据流" tabindex="-1">一、 为什么选择 ComfyUI？（潜空间数据流） <a class="header-anchor" href="#一、-为什么选择-comfyui-潜空间数据流" aria-label="Permalink to &quot;一、 为什么选择 ComfyUI？（潜空间数据流）&quot;">​</a></h2><p>传统的 WebUI（如 Automatic1111）像是一个封装好的软件界面，你点击按钮，后台自动帮你处理。而 <strong>ComfyUI 是一个可视化数据流引擎</strong>。</p><p>在 AI 绘图中，计算机并不是直接在像素（Pixels）上作画，而是在一个高度压缩的<strong>潜空间（Latent Space）<strong>中进行去噪推演。ComfyUI 把这个过程中的每一个步骤独立拆分为</strong>“节点（Nodes）”</strong>。</p><hr><h2 id="二、-通关-最基础的-5-大核心节点" tabindex="-1">二、 通关：最基础的 5 大核心节点 <a class="header-anchor" href="#二、-通关-最基础的-5-大核心节点" aria-label="Permalink to &quot;二、 通关：最基础的 5 大核心节点&quot;">​</a></h2><p>一个最简化的“文生图”工作流，必须由以下 <strong>5 个核心节点</strong> 互相连通：</p>',9)),(o(),s(A,null,{default:t(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BLoad%20Checkpoint%3Cbr%3E%E5%8A%A0%E8%BD%BD%E5%A4%A7%E6%A8%A1%E5%9E%8B%5D%20--%3E%7CMODEL%20%E7%BA%AF%E6%A8%A1%E5%9E%8B%7C%20D%5BKSampler%3Cbr%3E%E9%87%87%E6%A0%B7%E5%99%A8%E5%8E%BB%E5%99%AA%5D%0A%20%20%20%20A%20--%3E%7CCLIP%20%E6%96%87%E6%9C%AC%E8%A7%A3%E7%A0%81%E5%99%A8%7C%20B%5BCLIP%20Text%20Encode%3Cbr%3E%E6%AD%A3%E5%90%91%E6%8F%90%E7%A4%BA%E8%AF%8D%5D%0A%20%20%20%20A%20--%3E%7CCLIP%20%E6%96%87%E6%9C%AC%E8%A7%A3%E7%A0%81%E5%99%A8%7C%20C%5BCLIP%20Text%20Encode%3Cbr%3E%E8%B4%9F%E5%90%91%E6%8F%90%E7%A4%BA%E8%AF%8D%5D%0A%20%20%20%20A%20--%3E%7CVAE%20%E7%BC%96%E8%A7%A3%E7%A0%81%E5%99%A8%7C%20F%5BVAE%20Decode%3Cbr%3E%E6%BD%9C%E7%A9%BA%E9%97%B4%E8%A7%A3%E7%A0%81%5D%0A%20%20%20%20%0A%20%20%20%20B%20--%3E%7CCONDITIONING%7C%20D%0A%20%20%20%20C%20--%3E%7CCONDITIONING%7C%20D%0A%20%20%20%20%0A%20%20%20%20E%5BEmpty%20Latent%20Image%3Cbr%3E%E7%A9%BA%E7%99%BD%E6%BD%9C%E7%A9%BA%E9%97%B4%5D%20--%3E%7CLATENT%20%E5%99%AA%E5%A3%B0%E7%94%BB%E5%B8%83%7C%20D%0A%20%20%20%20%0A%20%20%20%20D%20--%3E%7CLATENT%20%E5%8E%BB%E5%99%AA%E5%90%8E%E7%BB%93%E6%9E%9C%7C%20F%0A%20%20%20%20F%20--%3E%7CIMAGE%20%E5%83%8F%E7%B4%A0%E5%9B%BE%E7%89%87%7C%20G%5BSave%20Image%3Cbr%3E%E4%BF%9D%E5%AD%98%E9%A2%84%E8%A7%88%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="_1-load-checkpoint-模型加载器" tabindex="-1">1. Load Checkpoint（模型加载器） <a class="header-anchor" href="#_1-load-checkpoint-模型加载器" aria-label="Permalink to &quot;1. Load Checkpoint（模型加载器）&quot;">​</a></h3><ul><li><strong>作用</strong>：载入你的主模型文件（.safetensors）。</li><li><strong>三大输出接口（线的颜色）</strong>： <ul><li>🟣 <strong>MODEL（紫色）</strong>：神经网络的主干去噪模型（UNet / Transformer）。</li><li>🟢 <strong>CLIP（绿色）</strong>：文本理解模型，负责把人类语言转成向量。</li><li>🔴 <strong>VAE（红色/粉色）</strong>：负责在“潜空间”与“真实像素图片”之间互相转换的解码器。</li></ul></li></ul><h3 id="_2-clip-text-encode-提示词编码节点" tabindex="-1">2. CLIP Text Encode（提示词编码节点） <a class="header-anchor" href="#_2-clip-text-encode-提示词编码节点" aria-label="Permalink to &quot;2. CLIP Text Encode（提示词编码节点）&quot;">​</a></h3><ul><li><strong>作用</strong>：输入提示词（Prompt），由 CLIP 模型将其转化为 AI 能听懂的引导条件（Conditioning）。</li><li><strong>标准配置</strong>：通常需要 <strong>2 个</strong> 该节点： <ul><li>一个作为<strong>正向提示词（Positive）</strong>：想要画面出现的元素。</li><li>一个作为<strong>负向提示词（Negative）</strong>：不想要出现的元素。</li></ul></li></ul><h3 id="_3-empty-latent-image-空白潜空间节点" tabindex="-1">3. Empty Latent Image（空白潜空间节点） <a class="header-anchor" href="#_3-empty-latent-image-空白潜空间节点" aria-label="Permalink to &quot;3. Empty Latent Image（空白潜空间节点）&quot;">​</a></h3><ul><li><strong>作用</strong>：为采样器提供一张“充满纯随机高斯噪声”的指定分辨率画布（例如：1024x1024）。</li><li><strong>重要概念</strong>：这里设置的 Width/Height 是潜空间尺寸，并不是最终渲染出来的图片尺寸（由于 VAE 8倍压缩，1024x1024 在潜空间实际只是 128x128 的向量矩阵）。</li></ul><h3 id="_4-ksampler-去噪采样器-——-核心发动机" tabindex="-1">4. KSampler（去噪采样器 —— 核心发动机） <a class="header-anchor" href="#_4-ksampler-去噪采样器-——-核心发动机" aria-label="Permalink to &quot;4. KSampler（去噪采样器 —— 核心发动机）&quot;">​</a></h3><ul><li><strong>作用</strong>：AI 绘画的核心算法引擎。它接收高斯噪声画布、提示词引导条件和模型，一步步剔除噪声（Denoise）。</li><li><strong>核心参数解析</strong>： <ul><li><code>seed</code>：随机种子。相同的 Seed + 相同的参数 = 100% 产生相同的图片。</li><li><code>steps</code>：去噪步数（通常 20-30 步）。</li><li><code>cfg</code>：提示词相关性。越大越严谨遵循提示词（一般设 7.0）。</li><li><code>sampler_name</code>：采样器算法（如 <code>euler</code>, <code>dpmpp_2m</code>）。</li><li><code>denoise</code>：去噪强度（1.0 代表完全重新去噪，图生图时常用小于 1.0）。</li></ul></li></ul><h3 id="_5-vae-decode-vae-解码节点" tabindex="-1">5. VAE Decode（VAE 解码节点） <a class="header-anchor" href="#_5-vae-decode-vae-解码节点" aria-label="Permalink to &quot;5. VAE Decode（VAE 解码节点）&quot;">​</a></h3><ul><li><strong>作用</strong>：将 KSampler 算好的“潜空间向量（Latent）”，翻译转换成人类眼睛看得懂的“RGB 像素图片（Image）”。</li><li><strong>终点</strong>：连接到 <code>Save Image</code> 或 <code>Preview Image</code> 节点显示结果。</li></ul><hr><h2 id="三、-实战避坑连线法则" tabindex="-1">三、 实战避坑连线法则 <a class="header-anchor" href="#三、-实战避坑连线法则" aria-label="Permalink to &quot;三、 实战避坑连线法则&quot;">​</a></h2><ol><li><strong>同色相连</strong>：紫色连紫色（MODEL）、绿色连绿色（CLIP）、黄色连黄色（CONDITIONING）、灰粉色连灰粉色（LATENT）、蓝色连蓝色（IMAGE）。</li><li><strong>红框报错</strong>：如果节点变成红色高亮，说明连线断开或缺少必要的依赖模型。</li></ol><hr><h2 id="四、-本课思考与练习" tabindex="-1">四、 本课思考与练习 <a class="header-anchor" href="#四、-本课思考与练习" aria-label="Permalink to &quot;四、 本课思考与练习&quot;">​</a></h2><ol><li>打开你的 ComfyUI，检查默认工作流是否包含这 5 大节点。</li><li>试着把 <code>Empty Latent Image</code> 的分辨率从 512x512 修改为 1024x1024，观察生成速度和画质的变化。</li></ol>',16))])}const I=l(c,[["render",m]]);export{B as __pageData,I as default};
